const {defaults,calculate}=FenceCalc;const inputs=Object.keys(defaults).map(k=>document.getElementById(k));const fmt=(n,d=2)=>n.toLocaleString(undefined,{maximumFractionDigits:d});
const shortLengths={east:0,north:0};const runMax={east:101.5,north:61.5};
function applyShortLength(run){const length=Math.max(0,Number(document.getElementById(run).value)||0),m=run==='east'?'em':'nm',t=run==='east'?'et':'nt';shortLengths[run]=Math.max(0,Math.min(length,shortLengths[run]));const short=shortLengths[run];document.getElementById(m).value=short===0?'6':short===length?'4':'split';document.getElementById(t).value=length-short;}
function applyHeightSlider(run){const position=Number(document.getElementById(run+'-height-slider').value),length=Number(document.getElementById(run).value);shortLengths[run]=run==='east'?length-position:position;applyShortLength(run);}
window.setFenceLength=(run,length)=>{const max=run==='east'?101.5:61.5;document.getElementById(run).value=Math.max(0,Math.min(max,Math.round(length*2)/2));applyShortLength(run);render();};
function render(){const v=Object.fromEntries(inputs.map(el=>[el.id,['em','nm'].includes(el.id)?el.value:el.value===''?NaN:Number(el.value)]));for(const [run,t]of [['east','et'],['north','nt']])if(Number.isFinite(v[run])&&v[run]>=0&&v[t]>v[run]){v[t]=v[run];document.getElementById(t).value=v[t];}
const c=calculate(v);document.getElementById('errors').innerHTML=c.errors.map(e=>`<p>${e}</p>`).join('');const out=document.getElementById('results');if(c.errors.length){out.innerHTML='';return;}
for(const [run,m,t]of [['east','em','et'],['north','nm','nt']]){const six=v[m]==='6'?v[run]:v[m]==='4'?0:v[t],slider=document.getElementById(run+'-height-slider');shortLengths[run]=v[run]-six;slider.max=v[run];slider.value=run==='east'?six:v[run]-six;slider.setAttribute('aria-valuemax',v[run]);slider.setAttribute('aria-valuenow',shortLengths[run]);slider.setAttribute('aria-valuetext',v[run]===0?'No fence':six===v[run]?'All 6 feet high':six===0?'All 4 feet high':`${fmt(v[run]-six)} feet of 4-foot fence; transition ${fmt(six)} feet from the northeast corner; short length stays fixed when resizing`);document.getElementById(run+'-transition-location').textContent=v[run]===0?'No fence on this run':six===v[run]?'All 6 ft high · no transition':six===0?'All 4 ft high · no transition':`6 → 4 ft at ${fmt(six)} ft from the NE corner`;document.getElementById(run+'-segment-summary').textContent=`${fmt(six)} ft at 6 ft high · ${fmt(v[run]-six)} ft at 4 ft high`;}
for(const run of ['east','north']){const lengthControl=document.getElementById('handle-'+run);lengthControl.max=runMax[run];lengthControl.value=v[run];lengthControl.setAttribute('aria-valuenow',v[run]);lengthControl.style.setProperty('--fill',(v[run]/Number(lengthControl.max)*100)+'%');lengthControl.setAttribute('aria-valuetext',v[run]===0?'No fence':fmt(v[run])+' feet');const splitControl=document.getElementById(run+'-height-slider');splitControl.style.setProperty('--fill',splitControl.value+'%');const card=document.querySelector('.'+run+'-control');card.style.setProperty('--length',v[run]/Number(lengthControl.max)*100+'%');card.style.setProperty('--four',(v[run]>0?shortLengths[run]/v[run]*100:0)+'%');const start=run==='east'?0:100-v[run]/runMax[run]*100,endpoint=run==='east'?v[run]/runMax[run]*100:start,divider=run==='east'?(v[run]-shortLengths[run])/runMax[run]*100:start+shortLengths[run]/runMax[run]*100;card.style.setProperty('--start',start+'%');card.style.setProperty('--endpoint',endpoint+'%');card.style.setProperty('--divider',divider+'%');card.classList.toggle('near-handles',Math.abs(endpoint-divider)<32);splitControl.disabled=v[run]===0;card.classList.toggle('empty-run',v[run]===0);document.getElementById(run+'-divide-label').textContent=fmt(shortLengths[run],1)+' ft short';document.getElementById(run+'-length-label').textContent=fmt(v[run],1)+' / '+lengthControl.max+' ft';}
const row=(title,sub,n)=>`<div class="bomrow"><div class="name">${title}<small>${sub}</small></div><strong>${n}</strong></div>`;
out.innerHTML=`<div class="totals"><strong>${fmt(c.total)} ft</strong> total · <strong>${c.posts}</strong> posts installed · <strong>${c.bays}</strong> bays</div>`+c.postGroups.map(g=>row(`${g.length} ft posts`,`${v.post} in actual square · ${g.qty} required`,g.buy)).join('')+c.railGroups.map(g=>row(`${g.length} ft rails`,`${g.qty} required · stock length covers each bay`,g.buy)).join('')+c.pickets.map(g=>row(`${g.length} ft pickets`,`${v.width} in wide · ${g.qty} required`,g.buy)).join('')+row('Concrete bags',`${v.yield} ft³ yield each · ${fmt(c.concrete)} ft³ net`,c.bags)+row('Gravel',`${fmt(c.gravelBuy/27)} cubic yards`,fmt(c.gravelBuy)+' ft³')+`<p class="allowance">Buy quantities include ${v.waste}% allowance. No gates.</p>`;
document.getElementById('math').innerHTML=c.runs.map(r=>`<p><strong>${r.name}:</strong> `+r.segments.map(s=>`${fmt(s.length)} ft at ${s.height} ft high: ${s.bays} bays × ${fmt(s.bayLength)} ft, ${s.railPieces} rails, ${s.pickets} pickets`).join('; ')+'.</p>').join('')+`<p>Corner post height: ${c.cornerHeight} ft above grade. Post embedment: ${fmt(c.embed)} ft. Net concrete per hole: ${fmt(c.concretePer,3)} ft³. ${c.posts} holes. Fastener planning allowances: ${c.picketScrews} picket fasteners and ${c.railScrews} rail fasteners, including waste; verify connection specification.</p>`;
window.fenceState={v,c};window.dispatchEvent(new CustomEvent('fencechange',{detail:{v,c}}));}
function reset(){inputs.forEach(el=>el.value=defaults[el.id]);render();window.dispatchEvent(new Event('fencefit'));}inputs.forEach(el=>el.addEventListener('input',()=>{if(['east','north'].includes(el.id))applyShortLength(el.id);render();}));for(const run of ['east','north']){
 const endpoint=document.getElementById('handle-'+run),transition=document.getElementById(run+'-height-slider');
 // Only the two handles accept pointer gestures. No upper/lower track hit regions.
 for(const [button,kind] of [[endpoint,'length'],[transition,'short']]){let drag=null;
 const position=()=>{const length=Number(document.getElementById(run).value);return kind==='length'?(run==='east'?length:runMax[run]-length):(run==='east'?length-shortLengths[run]:runMax[run]-length+shortLengths[run]);};
 const move=(coordinate)=>{const length=Number(document.getElementById(run).value);if(kind==='length'){window.setFenceLength(run,run==='east'?coordinate:runMax[run]-coordinate);}else{shortLengths[run]=Math.round((run==='east'?length-coordinate:coordinate-(runMax[run]-length))*2)/2;applyShortLength(run);render();}};
 button.addEventListener('pointerdown',e=>{if(button.disabled)return;e.preventDefault();button.setPointerCapture(e.pointerId);const track=button.closest('.profile-rectangle');drag={id:e.pointerId,x:e.clientX,start:position(),width:track.getBoundingClientRect().width};});
 button.addEventListener('pointermove',e=>{if(drag&&e.pointerId===drag.id){e.preventDefault();move(drag.start+(e.clientX-drag.x)/drag.width*runMax[run]);}});
 for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>{drag=null;});
 button.addEventListener('keydown',e=>{let next=position(),step=e.shiftKey?5:.5;if(['ArrowRight','ArrowUp'].includes(e.key))next+=step;else if(['ArrowLeft','ArrowDown'].includes(e.key))next-=step;else if(e.key==='Home')next=0;else if(e.key==='End')next=runMax[run];else return;e.preventDefault();move(next);});
 }
}
document.getElementById('reset').onclick=reset;document.getElementById('print').onclick=()=>window.print();reset();
